function contrast(string $a, string $b): float {
    $luminance = static function(string $hex): float {
        $rgb = array_map(static function($v) { $n = hexdec($v)/255; return $n <= .04045 ? $n/12.92 : (($n+.055)/1.055)**2.4; }, str_split(ltrim($hex, '#'), 2));
        return .2126*$rgb[0]+.7152*$rgb[1]+.0722*$rgb[2];
    };
    $x=$luminance($a); $y=$luminance($b); return (max($x,$y)+.05)/(min($x,$y)+.05);
}
